"""A row generated by ``create()`` has its log filed under that row, on every synchronous route.

Intent: docs/calculations/logging.md ("Nested Calculations") promises that a
child calculation's lines appear nested under the calculation that triggered
it, at any depth, with no ids passed by hand. docs/reference/CalculatedModelMixin
Internals.md promises that the framework sets that context for every generated
row. The 15b-15e batches pin the default route with an atomic root. This batch
pins the remaining synchronous combinations, where the same promise holds:

- ``LEX_SYNC_STREAMING_EXPANSION=false`` sends ``create()`` through the
  materialising pipeline and ``calc_and_save_sync`` rather than
  ``calc_and_save_streaming``.
- With a non-atomic root (``is_atomic = False``) a line is written the moment
  it is logged. A new row has no primary key yet while its ``calculate()``
  runs, so the line cannot be filed by object_id. Each row must still get a
  node of its own, linked to the record once it is saved, and siblings must
  never share a node.

Why a regression matters: from 2026-05-14 (eec74b6d) until this batch, every
generated row's lines were filed under the root on every route. Earlier, a
non-atomic root merged all new siblings' lines into one node with no record.
Both bury the line a reviewer is looking for, or attach it to the wrong record.

Cluster 15m — scenarios 15.56–15.62. Type: I.
Covers: lex/core/mixins/CalculatedModelMixin.py (calc_and_save_streaming,
calc_and_save_sync), lex/core/models/CalculationModel.py
(child_calculation_context), lex/audit_logging/models/CalculationLog.py (rows of
unsaved models, parents logged for first by a child),
lex/audit_logging/utils/ModelContext.py (rows linked when a block ends).
Run: python -m lex pytest lex/test_project/tests/calculation_logging/test_15m_generated_row_log.py -v
"""
from __future__ import annotations

import os
from contextlib import contextmanager
from unittest.mock import patch

import pytest

import lex.core.mixins.CalculatedModelMixin as calculated_model_mixin
from lex.api.utils import operation_context
from lex.audit_logging.models.CalculationLog import CalculationLog

from . import _CalcLogTestCase, _seed_operation_context_and_audit_log
from .models import (
    ALL_MODELS,
    GENERATED_ROW_MODELS,
    LogFailingChild,
    LogGrandchildCalc,
    LogLoudChild,
    LogQuietMiddle,
    LogRootCalc,
)

pytestmark = pytest.mark.calculation_logging


@contextmanager
def _route(consumer_name):
    """Watch one batch consumer of CalculatedModelMixin, so a scenario can
    check that it really ran on the route it claims to cover."""
    consumer = getattr(calculated_model_mixin, consumer_name)
    with patch.object(calculated_model_mixin, consumer_name, wraps=consumer) as spy:
        yield spy


@contextmanager
def _materialising_route():
    with patch.dict(os.environ, {"LEX_SYNC_STREAMING_EXPANSION": "false"}):
        yield


@contextmanager
def _non_atomic_root():
    with patch.object(LogRootCalc, "is_atomic", False):
        yield


class TestCluster15m_GeneratedRowLog(_CalcLogTestCase):
    """Cluster 15m: every generated row gets its own node, under its trigger."""

    e2e_models = ALL_MODELS + GENERATED_ROW_MODELS

    def _assert_one_row_per_loud_child(self, root, units):
        root_row = self.assert_log_row(root, parent=None, contains=f"root {root.name}")
        for unit in units:
            child = LogLoudChild.objects.get(unit=unit)
            self.assert_log_row(child, parent=root_row, contains=f"loud {unit}")
        self.assertFalse(
            CalculationLog.objects.filter(
                calculationId=self.calc_id,
                content_type__model="logloudchild",
                object_id__isnull=True,
            ).exists(),
            "Every child row is saved, so no node of theirs may be left without its record.",
        )
        self.assert_total_rows(1 + len(units))

    def test_15_56_materialising_route_files_each_row_under_itself(self):
        """
        Scenario 15.56: the materialising route files each generated row's lines under that row
        Given: LEX_SYNC_STREAMING_EXPANSION=false and an atomic root whose
               calculate() runs LogLoudChild.create(unit=[u1, u2, u3])
        When:  the root is saved and calculates
        Then:  calc_and_save_sync processes the rows, and each child gets
               exactly one log row keyed by its pk, under the root's row
        """
        with _materialising_route(), _route("calc_and_save_sync") as sync_consumer:
            root = self._save_root(child_mode="loud", units_csv="u1,u2,u3")

        self.assertTrue(
            sync_consumer.called,
            "Sanity: with the flag off, the rows must go through calc_and_save_sync.",
        )
        self._assert_one_row_per_loud_child(root, ("u1", "u2", "u3"))

    def test_15_57_streaming_route_non_atomic_root_keeps_siblings_apart(self):
        """
        Scenario 15.57: rows logged before they have a pk still get one node each (streaming route)
        Given: a non-atomic root, so every line is written as it is logged,
               while each new LogLoudChild has no primary key yet
        When:  the root runs LogLoudChild.create(unit=[u1, u2, u3])
        Then:  each child has exactly one row, keyed by its pk once saved,
               under the root's row, and holding only its own line
        """
        with _non_atomic_root(), _route("calc_and_save_streaming") as streaming_consumer:
            root = self._save_root(child_mode="loud", units_csv="u1,u2,u3")

        self.assertTrue(
            streaming_consumer.called,
            "Sanity: by default the rows must go through calc_and_save_streaming.",
        )
        self._assert_one_row_per_loud_child(root, ("u1", "u2", "u3"))
        for unit, other in (("u1", "u2"), ("u2", "u3"), ("u3", "u1")):
            row = CalculationLog.objects.get(
                calculationId=self.calc_id,
                content_type__model="logloudchild",
                object_id=LogLoudChild.objects.get(unit=unit).pk,
            )
            self.assertNotIn(
                f"loud {other}", row.calculation_log,
                f"The row of {unit} must not carry the line of its sibling {other}.",
            )

    def test_15_58_materialising_route_non_atomic_root_keeps_siblings_apart(self):
        """
        Scenario 15.58: rows logged before they have a pk still get one node each (materialising route)
        Given: LEX_SYNC_STREAMING_EXPANSION=false and a non-atomic root
        When:  the root runs LogLoudChild.create(unit=[u1, u2])
        Then:  calc_and_save_sync processes the rows, and each child has exactly
               one row, keyed by its pk once saved, under the root's row
        """
        with _non_atomic_root(), _materialising_route(), _route("calc_and_save_sync") as sync_consumer:
            root = self._save_root(child_mode="loud", units_csv="u1,u2")

        self.assertTrue(
            sync_consumer.called,
            "Sanity: with the flag off, the rows must go through calc_and_save_sync.",
        )
        self._assert_one_row_per_loud_child(root, ("u1", "u2"))

    def test_15_59_rerun_files_lines_under_the_stored_rows(self):
        """
        Scenario 15.59: a second run files each line under the row that is already stored
        Given: a first run that created LogLoudChild rows u1 and u2
        When:  a second calculation (its own calculationId) runs the same
               create(), which finds both combinations already stored
        Then:  the second run's lines are filed under the stored rows' pks,
               under the second root's row, and no row is left without its record
        """
        self._save_root(child_mode="loud", units_csv="u1,u2")
        stored = {child.unit: child.pk for child in LogLoudChild.objects.all()}

        second_calc_id, _audit_log, token = _seed_operation_context_and_audit_log()
        try:
            second_root = self._save_root(child_mode="loud", units_csv="u1,u2")
        finally:
            operation_context.reset(token)

        self.assertEqual(
            {child.unit: child.pk for child in LogLoudChild.objects.all()}, stored,
            "Sanity: the second run must update the stored rows, not add new ones.",
        )
        second_root_row = CalculationLog.objects.get(
            calculationId=second_calc_id,
            content_type__model="logrootcalc",
            object_id=second_root.pk,
        )
        for unit, pk in stored.items():
            rows = list(CalculationLog.objects.filter(
                calculationId=second_calc_id,
                content_type__model="logloudchild",
                object_id=pk,
            ))
            self.assertEqual(
                len(rows), 1,
                f"The second run must file the line of {unit} under the stored row (pk={pk}).",
            )
            self.assertEqual(rows[0].parent_log_id, second_root_row.pk)
            self.assertIn(f"loud {unit}", rows[0].calculation_log)
        self.assertFalse(
            CalculationLog.objects.filter(
                calculationId=second_calc_id, object_id__isnull=True, heading__isnull=True,
            ).exists(),
            "A line filed under the generated copy instead of the stored row has no record.",
        )

    def _assert_quiet_middle_chain(self, root):
        root_row = self.assert_log_row(root, parent=None)
        middle = LogQuietMiddle.objects.get(unit="u1")
        middle_row = self.assert_log_row(middle, parent=root_row, contains="middle after u1")
        grandchild = LogGrandchildCalc.objects.get(unit="u1")
        self.assert_log_row(grandchild, parent=middle_row, contains="grandchild u1")
        self.assertEqual(
            CalculationLog.objects.filter(
                calculationId=self.calc_id, content_type__model="logquietmiddle",
            ).count(),
            1,
            "The middle must be one node, holding its own line and its grandchild.",
        )
        self.assert_total_rows(3)

    def test_15_60_middle_logging_after_its_children_is_one_node_atomic_root(self):
        """
        Scenario 15.60: a middle that logs only after its grandchild is one node, under the root (atomic root)
        Given: an atomic root running LogQuietMiddle.create(unit=[u1]), whose
               calculate() runs LogGrandchildCalc.create() before logging
        When:  the root is saved and calculates
        Then:  there is exactly one middle row, under the root's row and holding
               "middle after u1", and the grandchild's row hangs off it
        """
        root = self._save_root(child_mode="quiet_three_level", units_csv="u1")
        self._assert_quiet_middle_chain(root)

    def test_15_61_middle_logging_after_its_children_is_one_node_non_atomic_root(self):
        """
        Scenario 15.61: the same chain is one node per model when lines are written immediately
        Given: a non-atomic root, so the grandchild's line is written while the
               middle has no primary key and no row of its own yet
        When:  the root runs LogQuietMiddle.create(unit=[u1])
        Then:  exactly one middle row exists, keyed by the middle's pk once
               saved, under the root's row, with the grandchild's row under it
        """
        with _non_atomic_root():
            root = self._save_root(child_mode="quiet_three_level", units_csv="u1")
        self._assert_quiet_middle_chain(root)

    def test_15_62_failing_row_keeps_its_lines_and_leaves_no_frame_behind(self):
        """
        Scenario 15.62: a row that fails keeps its lines in its own node, and the trigger logs on its own node
        Given: a root running LogFailingChild.create(unit=[ok, bad]); "bad"
               logs a line and then raises, which stops the batch
        When:  the root catches the failure and logs "root recovered"
        Then:  "ok" has its row under the root's row; "bad" was never saved, so
               its line sits in a node of its own with no record, under the
               root's row; "root recovered" lands on the root's own row
        """
        root = self._save_root(child_mode="fail_child_then_log", units_csv="ok,bad")

        self.assertFalse(
            LogFailingChild.objects.filter(unit="bad").exists(),
            "Sanity: the failing row must not have been saved.",
        )
        root_row = self.assert_log_row(root, parent=None, contains="root recovered")
        self.assertNotIn(
            "before failure", root_row.calculation_log,
            "The children's lines must not be filed under the root.",
        )
        ok = LogFailingChild.objects.get(unit="ok")
        self.assert_log_row(ok, parent=root_row, contains="before failure ok")
        bad_rows = list(CalculationLog.objects.filter(
            calculationId=self.calc_id,
            content_type__model="logfailingchild",
            object_id__isnull=True,
        ))
        self.assertEqual(
            len(bad_rows), 1,
            "The failing row's line must sit in one node of its own.",
        )
        self.assertEqual(bad_rows[0].parent_log_id, root_row.pk)
        self.assertIn("before failure bad", bad_rows[0].calculation_log)
        self.assertNotIn("before failure ok", bad_rows[0].calculation_log)
        self.assert_total_rows(3)
